#!/usr/bin/env python3
# Generated by Claude Fable 5.1 (Anthropic)
"""dag_gallery_pg — static gallery of a session's GPU typed DAGs, conditional
graphs (LCS skeleton + branches) and FISH tasks (WCCs of the F-graph), in the
style of the April 2026 skeleton index (notes/skeleton_index.html).

Data: PostgreSQL only (gpu_dags from gpu_dag_pg.py, graph_nodes/graph_edges
from model_improved_pg.py). Figures per GPU anchor (callback or thread):
  fig1  dominant typed DAG (CPU / SM / CE nodes, launch / cpu_order /
        stream_fifo edges, per-node C ranges)         — fish_viz_server._typed_dag_dot
  fig2  conditional graph: LCS skeleton + branches with probabilities
                                                       — fish_viz_server._conditional_dot
  fig3  shape catalogue: every observed shape (top N) side by side with its
        phase label and share of invocations
FISH tasks: graph exported with graph_store_pg.to_viz_json, rendered by
wcc_dag_viz.py; tasks are split into "CPU–GPU" (contain a GPU submitter) and
"CPU-only".

Usage:
  python3 -m postprocess.dag_gallery_pg <session_id> [--scope __main__]
      [-o paper/dag_gallery/<session_id>] [--max-shapes 8] [--no-wcc]
"""
from __future__ import annotations
import argparse, collections, html, json, os, re, subprocess, sys, datetime
HERE = os.path.dirname(os.path.abspath(__file__))
sys.path.insert(0, HERE)
import psycopg2, psycopg2.extras
import fish_viz_server as vs          # has a __main__ guard; gives _typed_dag_dot / _conditional_dot / _esc
import graph_store_pg as gs

DSN = os.environ.get('FISH_PG_DSN', 'host=localhost port=5432 dbname=fish user=fish password=fish')
PE_FILL = {'CPU': ('box', '#eeeeee'), 'SM': ('ellipse', '#a9dfbf'), 'CE': ('parallelogram', '#f9d5a7')}
PHASE_COLOR = {'STEADY': '#2E7D32', 'INIT': '#1976D2', 'WARMUP': '#0288D1', 'TAIL': '#7B1FA2', 'COALESCED': '#F57C00', 'UNKNOWN': '#9E9E9E'}

CSS = """
body { font-family: system-ui, sans-serif; max-width: 1500px; margin: 1em auto; color: #222; }
h1 { font-size: 1.5em; margin-bottom: 0.3em; }
h2 { font-size: 1.05em; margin: 0.2em 0; color: #1a5490; }
h3 { font-size: 1.15em; margin: 1.4em 0 0.4em 0; border-bottom: 2px solid #1a5490; }
.meta { color: #666; font-size: 0.85em; margin-bottom: 0.8em; }
.cb { border: 1px solid #ddd; border-radius: 6px; padding: 0.8em 1em; margin-bottom: 1em; background: #fafafa; }
.stats { display: inline-block; margin-right: 0.4em; padding: 2px 8px; background: #e3f2fd; border-radius: 3px; font-family: ui-monospace, Menlo, monospace; font-size: 0.85em; }
.stats.alt { background: #fff3e0; }
.stats.gold { background: #fff8e1; }
.stats.gpu { background: #fdecea; }
.label { font-family: ui-monospace, Menlo, monospace; font-size: 0.78em; color: #555; word-break: break-all; margin: 0.4em 0 0.6em 0; }
.nick { font-weight: 600; color: #2e7d32; font-size: 1em; }
.figs { display: flex; gap: 8px; flex-wrap: wrap; }
.fig { flex: 1; min-width: 350px; max-width: 500px; }
.fig img { width: 100%; height: auto; border: 1px solid #ccc; border-radius: 4px; cursor: pointer; background: white; }
.fig img:hover { border-color: #1a5490; }
.fig-cap { font-size: 0.78em; color: #666; text-align: center; margin: 2px 0; }
table { border-collapse: collapse; margin: 0.5em 0 1.5em 0; }
th, td { border: 1px solid #ccc; padding: 4px 8px; font-size: 0.9em; }
th { background: #eee; }
a { color: #1a5490; }
code { font-size: 0.85em; }
"""


def esc(s):
    return html.escape(str(s))


def dot_render(dot_src, base):
    with open(base + '.dot', 'w') as f:
        f.write(dot_src)
    try:
        subprocess.check_call(['dot', '-Tsvg', base + '.dot', '-o', base + '.svg'],
                              stderr=subprocess.DEVNULL, timeout=300)
        return True
    except Exception as e:
        print(f'[gallery] dot failed for {base}: {e}')
        return False


def april_style(dot_src, title):
    """Give the server's typed-DAG dot the April look (rounded boxes, tight
    ranks, top-left title)."""
    dot_src = dot_src.replace('node [fontname="Helvetica", fontsize=9, style=filled];',
                              'node [fontname="Helvetica", fontsize=8, style="filled,rounded", margin="0.05,0.02"];\n'
                              'graph [nodesep=0.15, ranksep=0.25]; edge [fontname="Helvetica", fontsize=7];')
    dot_src = re.sub(r'label="[^"]*"; labelloc=t; fontsize=12;',
                     f'label="{vs._esc(title)}"; labelloc=t; labeljust=l; fontsize=10;', dot_src, count=1)
    return dot_src


def shape_catalogue_dot(shapes, title, max_shapes):
    """fig3: every observed shape as its own cluster (linear typed chain with
    the shape's own edges), labelled with phase, count and share."""
    total = sum(int(s.get('count') or 0) for s in shapes) or 1
    L = ['digraph catalogue {', 'rankdir=LR; bgcolor=white; fontname="Helvetica";',
         f'label="{vs._esc(title)}"; labelloc=t; labeljust=l; fontsize=10;',
         'node [fontname="Helvetica", fontsize=8, style="filled,rounded", margin="0.05,0.02"];',
         'edge [arrowsize=0.5, fontname="Helvetica", fontsize=7]; graph [nodesep=0.12, ranksep=0.2];']
    shown = 0
    for i, s in enumerate(sorted(shapes, key=lambda x: -int(x.get('count') or 0))):
        if shown >= max_shapes:
            break
        cnt = int(s.get('count') or 0); ph = s.get('phase') or '?'
        col = PHASE_COLOR.get(ph, '#9E9E9E')
        if s.get('truncated') or not s.get('nodes'):
            L.append(f'subgraph cluster_t{i} {{ label="shape {i} · {ph} · ×{cnt} ({100*cnt/total:.1f}%) · stored as summary"; '
                     f'color="{col}"; fontsize=9; t{i} [shape=note, fillcolor="#FFFFFF", label="{s.get("n_nodes","?")} nodes / {s.get("n_edges","?")} edges"]; }}')
            shown += 1; continue
        nodes = s['nodes']
        if len(nodes) > 120:
            L.append(f'subgraph cluster_t{i} {{ label="shape {i} · {ph} · ×{cnt} ({100*cnt/total:.1f}%) · {len(nodes)} nodes (not drawn)"; '
                     f'color="{col}"; fontsize=9; t{i} [shape=note, fillcolor="#FFFFFF", label="sig {str(s.get("signature",""))[:12]}"]; }}')
            shown += 1; continue
        L.append(f'subgraph cluster_s{i} {{ label="shape {i} · {ph} · ×{cnt} ({100*cnt/total:.1f}%) · sig {str(s.get("signature",""))[:8]}"; '
                 f'color="{col}"; penwidth=2; fontname="Helvetica-Bold"; fontsize=9;')
        for n in nodes:
            shape, fill = PE_FILL.get(n.get('pe'), ('box', '#ffffff'))
            nm = (n.get('name') or '?')[:28]
            extra = f"\\n{n['c_min_ns']/1e3:.0f}–{n['c_max_ns']/1e3:.0f} µs" if 'c_min_ns' in n and n.get('pe') != 'CPU' else ''
            L.append(f's{i}n{n["idx"]} [shape={shape}, fillcolor="{fill}", label="{n["idx"]}\\n{n.get("pe","?")}:{vs._esc(nm)}{extra}"];')
        STYLE = {'launch': 'color="#2c3e50"', 'cpu_order': 'color="#bbbbbb", penwidth=0.6', 'stream_fifo': 'color="#27ae60", style=dashed'}
        for (u, v, lbl) in s.get('edges', []):
            L.append(f's{i}n{u} -> s{i}n{v} [{STYLE.get(lbl, "")}];')
        L.append('}')
        shown += 1
    L.append('}')
    return '\n'.join(L)


def anchor_stats(shapes):
    total = sum(int(s.get('count') or 0) for s in shapes)
    phases = collections.Counter()
    for s in shapes:
        phases[s.get('phase') or '?'] += int(s.get('count') or 0)
    # dominant = the most frequent drawable non-INIT shape. NOT "the STEADY one":
    # the phase classifier scores cudaMalloc calls as init signals, so a node
    # that allocates every frame (lidar_centerpoint: 206-node shape, 94 % of
    # invocations) is labelled UNKNOWN and a marginal 8-node shape gets STEADY.
    cands = [s for s in shapes if not s.get('truncated') and s.get('nodes') and s.get('phase') != 'INIT'] or [s for s in shapes if not s.get('truncated') and s.get('nodes')] or shapes
    dom = max(cands, key=lambda s: int(s.get('count') or 0))
    def busy(pe):
        lo = sum(n.get('c_min_ns', 0) for n in dom.get('nodes', []) if n.get('pe') == pe) / 1e3
        hi = sum(n.get('c_max_ns', 0) for n in dom.get('nodes', []) if n.get('pe') == pe) / 1e3
        return (lo, hi)
    streams = sorted({n.get('stream') for s in shapes for n in s.get('nodes', []) if n.get('stream') is not None})
    return {'total': total, 'phases': dict(phases), 'dominant': dom, 'dom_share': (int(dom.get('count') or 0) / total * 100) if total else 0,
            'n_nodes': len(dom.get('nodes', [])), 'sm': busy('SM'), 'ce': busy('CE'),
            'n_sm': sum(1 for n in dom.get('nodes', []) if n.get('pe') == 'SM'), 'n_ce': sum(1 for n in dom.get('nodes', []) if n.get('pe') == 'CE'),
            'n_cpu': sum(1 for n in dom.get('nodes', []) if n.get('pe') == 'CPU'), 'streams': streams}


def render_wccs(session, scope, outdir):
    """Export the graph, run wcc_dag_viz.py, classify every rendered WCC."""
    wdir = os.path.join(outdir, 'wcc'); os.makedirs(wdir, exist_ok=True)
    gjson = os.path.join(wdir, 'fish_graph.json')
    gs.export_json(session, scope, gjson)
    cmd = [sys.executable, os.path.join(HERE, 'wcc_dag_viz.py'), '--session', session, '--graph-json', gjson, '-o', wdir, '--data-only']
    log = subprocess.run(cmd, capture_output=True, text=True)
    open(os.path.join(wdir, 'wcc_dag_viz.log'), 'w').write(log.stdout + log.stderr)
    tasks = []
    for dot in sorted(f for f in os.listdir(wdir) if re.match(r'wcc_\d+\.dot$', f)):
        src = open(os.path.join(wdir, dot)).read()
        n_gpu = len(re.findall(r'penwidth="?3"?', src)); n_nodes = len(re.findall(r'^\s*"?[^"\s\[]+"?\s*\[label=', src, re.M))
        names = re.findall(r'label="([^"\\]{2,60})', src)
        tasks.append({'file': dot[:-4], 'n_nodes': n_nodes, 'n_gpu': n_gpu, 'names': names[:4],
                      'svg': os.path.exists(os.path.join(wdir, dot[:-4] + '.svg'))})
    return tasks


def main():
    ap = argparse.ArgumentParser(description=__doc__, formatter_class=argparse.RawDescriptionHelpFormatter)
    ap.add_argument('session'); ap.add_argument('--scope', default='__main__')
    ap.add_argument('-o', '--outdir', default=None); ap.add_argument('--max-shapes', type=int, default=8)
    ap.add_argument('--no-wcc', action='store_true')
    a = ap.parse_args()
    outdir = a.outdir or os.path.join('paper', 'dag_gallery', a.session)
    dout = os.path.join(outdir, 'dag_out'); os.makedirs(dout, exist_ok=True)
    conn = psycopg2.connect(DSN, cursor_factory=psycopg2.extras.RealDictCursor); cur = conn.cursor()
    cur.execute("SELECT start_utc, target_image, nsys_flags, tracepoint_count FROM sessions WHERE session_id=%s", (a.session,))
    sess = cur.fetchone() or {}
    cur.execute("""SELECT anchor_type, anchor, node, entity, n_invocations, n_shapes, dags FROM gpu_dags
                   WHERE session_id=%s AND scope=%s ORDER BY n_invocations DESC""", (a.session, a.scope))
    rows = cur.fetchall()
    print(f'[gallery] {len(rows)} GPU anchors')
    blocks = []; summary = []
    for i, r in enumerate(rows):
        shapes = r['dags'] if isinstance(r['dags'], list) else json.loads(r['dags'])
        st = anchor_stats(shapes)
        tag = f"{'cb' if r['anchor_type']=='cb' else 'tid'}_{str(r['anchor']).replace('0x','').lower()}"
        nick = f"{r['node']} ← {r['entity']}" if r['entity'] else r['node']
        title1 = f"{tag} fig1: dominant typed DAG — {st['dominant'].get('phase','?')} shape ×{st['dominant'].get('count',0)} ({st['dom_share']:.1f}% of {st['total']} inv), {st['n_cpu']} CPU / {st['n_sm']} SM / {st['n_ce']} CE nodes"
        f1 = dot_render(april_style(vs._typed_dag_dot(st['dominant'], title1), title1), os.path.join(dout, f'{tag}_fig1')) if st['dominant'].get('nodes') and len(st['dominant']['nodes']) <= 400 else False
        cdot = vs._conditional_dot(shapes, f"{tag} fig2: conditional graph — LCS skeleton + branches, {len(shapes)} shapes / {st['total']} inv")
        f2 = dot_render(cdot, os.path.join(dout, f'{tag}_fig2')) if cdot else False
        f3 = dot_render(shape_catalogue_dot(shapes, f"{tag} fig3: shape catalogue (top {a.max_shapes} of {len(shapes)} shapes)", a.max_shapes), os.path.join(dout, f'{tag}_fig3'))
        phases_txt = ', '.join(f'{k}={v}' for k, v in sorted(st['phases'].items(), key=lambda kv: -kv[1]))
        chips = (f'<span class="stats">invocations={st["total"]}</span><span class="stats">shapes={len(shapes)}</span>'
                 f'<span class="stats alt">dominant={st["dom_share"]:.0f}% ({st["dominant"].get("phase","?")})</span>'
                 f'<span class="stats gold">nodes={st["n_nodes"]} (CPU {st["n_cpu"]} / SM {st["n_sm"]} / CE {st["n_ce"]})</span>'
                 f'<span class="stats gpu">SM busy {st["sm"][0]:.0f}–{st["sm"][1]:.0f} µs · CE {st["ce"][0]:.0f}–{st["ce"][1]:.0f} µs</span>'
                 + (f'<span class="stats">streams={st["streams"]}</span>' if st['streams'] else '')
                 + f'<span class="stats">phases: {esc(phases_txt)}</span>')
        figs = ''
        for k, ok, cap in ((1, f1, 'fig1: dominant typed DAG (CPU/SM/CE, launch · cpu_order · stream_fifo)'),
                           (2, f2, 'fig2: conditional graph — LCS skeleton + branches (probabilities)'),
                           (3, f3, 'fig3: shape catalogue — every observed shape, phase-coloured, share of invocations')):
            if ok:
                p = f'dag_out/{tag}_fig{k}.svg'
                figs += f'<div class="fig"><a href="{p}" target="_blank"><img src="{p}" loading="lazy"></a><div class="fig-cap">{cap} · <a href="{p}">svg</a></div></div>'
            else:
                figs += f'<div class="fig"><div class="fig-cap">{cap} — not drawn</div></div>'
        blocks.append(f'<div class="cb" id="{tag}"><h2><span class="nick">{esc(nick)}</span> &nbsp; <code>{esc(r["anchor_type"])} {esc(r["anchor"])}</code></h2>'
                      f'<div>{chips}</div><div class="label">dominant signature {esc(str(st["dominant"].get("signature",""))[:32])}</div><div class="figs">{figs}</div></div>')
        summary.append(f'<tr><td><a href="#{tag}">{esc(tag)}</a></td><td>{esc(nick)}</td><td>{st["total"]}</td><td>{len(shapes)}</td>'
                       f'<td>{st["dom_share"]:.0f}% {esc(st["dominant"].get("phase","?"))}</td><td>{st["n_cpu"]}/{st["n_sm"]}/{st["n_ce"]}</td>'
                       f'<td>{st["sm"][0]:.0f}–{st["sm"][1]:.0f}</td><td>{esc(phases_txt)}</td></tr>')
    # FISH tasks
    task_html = ''
    if not a.no_wcc:
        try:
            tasks = render_wccs(a.session, a.scope, outdir)
            gpu_tasks = [t for t in tasks if t['n_gpu'] > 0]; cpu_tasks = [t for t in tasks if t['n_gpu'] == 0]
            def ttable(ts):
                if not ts: return '<p>none</p>'
                rows_ = ''.join(f'<tr><td><a href="wcc/{t["file"]}.svg" target="_blank">{t["file"]}</a></td><td>{t["n_nodes"]}</td><td>{t["n_gpu"]}</td>'
                                f'<td>{esc(", ".join(t["names"]))}</td></tr>' for t in ts)
                return f'<table><tr><th>task (WCC)</th><th>F vertices</th><th>GPU submitters</th><th>first vertices</th></tr>{rows_}</table>'
            thumbs = ''.join(f'<div class="fig"><a href="wcc/{t["file"]}.svg" target="_blank"><img src="wcc/{t["file"]}.png" loading="lazy"></a>'
                             f'<div class="fig-cap">{t["file"]} · {t["n_nodes"]} F · {t["n_gpu"]} GPU submitters</div></div>' for t in gpu_tasks if os.path.exists(os.path.join(outdir, 'wcc', t['file'] + '.png')))
            task_html = (f'<h3>FISH tasks (weakly connected components of the F-graph on data edges)</h3>'
                         f'<p class="meta">{len(tasks)} tasks rendered (≥2 F vertices); GPU submitters have a red border in the task figures. '
                         f'Tasks with CPU–GPU interaction: {len(gpu_tasks)}, CPU-only: {len(cpu_tasks)}.</p>'
                         f'<h2>CPU–GPU tasks</h2>{ttable(gpu_tasks)}<div class="figs">{thumbs}</div><h2>CPU-only tasks</h2>{ttable(cpu_tasks)}')
        except Exception as e:
            task_html = f'<h3>FISH tasks</h3><p>WCC rendering failed: {esc(e)}</p>'
    meta = (f'session {esc(a.session)} · scope {esc(a.scope)} · started {esc(sess.get("start_utc",""))} · image {esc(sess.get("target_image",""))} · '
            f'{len(rows)} GPU anchors · generated {datetime.datetime.now():%Y-%m-%d %H:%M} by postprocess/dag_gallery_pg.py')
    page = (f'<!DOCTYPE html><html><head><meta charset="utf-8"><title>FISH DAG gallery — {esc(a.session)}</title><style>{CSS}</style></head><body>'
            f'<h1>FISH DAG gallery — {esc(a.session)}</h1><div class="meta">{meta}</div>'
            f'<h2>Index — GPU anchors (callbacks and out-of-ROS threads that submit GPU work)</h2>'
            f'<table><tr><th>anchor</th><th>node ← entity</th><th>inv</th><th>shapes</th><th>dominant</th><th>CPU/SM/CE</th><th>SM busy [µs]</th><th>phases</th></tr>{"".join(summary)}</table>'
            + ''.join(blocks) + task_html + '</body></html>')
    open(os.path.join(outdir, 'index.html'), 'w').write(page)
    print(f'[gallery] written {os.path.join(outdir, "index.html")} ({len(blocks)} anchors)')


if __name__ == '__main__':
    main()
